import {mountCaptcha} from './captcha.js';
const form=document.getElementById('tracking-form'),status=document.getElementById('tracking-status'),results=document.getElementById('tracking-results'),captcha=mountCaptcha(document.getElementById('tracking-captcha'),'tracking');captcha.refresh();
form.addEventListener('submit',async e=>{e.preventDefault();const button=form.querySelector('button[type=submit]'),identifier=form.elements.identifier.value.trim();if(!/^([6-9]\d{9}|(?:S[1-5]|K[1-4])-\d{4}|[a-f0-9]{8}-(?:[a-f0-9]{4}-){3}[a-f0-9]{12})$/i.test(identifier)){status.textContent='Enter your registered mobile number or a booking ID such as S1-4827 or K1-4827.';return;}if(!captcha.values().captchaId){status.textContent='Complete the verification first.';return;}button.disabled=true;results.replaceChildren();status.textContent='Checking your request…';try{const r=await fetch('/api/bookings',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'track',identifier,...captcha.values()}),signal:AbortSignal.timeout(25000)});const data=await r.json();if(!r.ok)throw Error(data.error||'Unable to check your request.');status.textContent=data.requests.length?'Request status updated.':'No request found. Check your mobile number or booking ID.';for(const request of data.requests){const card=document.createElement('article');card.className='booking-card tracking-result';const title=document.createElement('h2');title.textContent=request.status[0].toUpperCase()+request.status.slice(1);const ref=document.createElement('p');ref.textContent='Booking ID: '+request.reference;const summary=document.createElement('p');summary.textContent=request.status==='approved'?`Approved: ${request.grade} · Section ${request.section} · ${request.slot}`:request.status==='pending'?`Requested: ${request.grade} · Section ${request.requestedSection} · ${request.requestedSlot}`:'Your request was rejected. You may submit a new request with correct details.';const note=document.createElement('p');note.textContent=request.status==='pending'?'Your request is awaiting review by the SFIS team.':request.status==='approved'?'Your request is approved. This number is a booking reference, not a permanent classroom seating assignment.':'For clarification, please contact the SFIS team.';card.append(title,ref,summary,note);results.append(card);}}catch(e){status.textContent=e.name==='TimeoutError'?'The connection timed out. Please retry.':e.message;}finally{button.disabled=false;await captcha.refresh();}});
